/**
 * @file ItemDB.js
 * @brief Read-only repository of the items (C++: class ItemDB : public DataRepository).
 * Built from data/raw/items-data.js (generated by tools/data/gen-items.mjs). Every entry is a
 * frozen ItemDefinition:
 *   { id, kind, price, buyable, hidden, category|null, effect|null, move|null,
 *     ball: { rate, sprite, bonus, condition|null, order } | null,
 *     revives|null, futureOnly, value, diamondValue, image|null }
 * Texts: t('item.<id>.name') / t('item.<id>.desc'). Paths are resolved by AssetPaths here only.
 */
import { DataRepository, deepFreeze } from '../core/DataRepository.js';
import { ITEMS_TABLE as GENERATED_ITEMS } from '../raw/items-data.js';
import { ITEMS_CONTENT } from '../content/items-content.js';
import { withContent } from '../core/ContentTables.js';

const ITEMS_TABLE = withContent(GENERATED_ITEMS, ITEMS_CONTENT);
import { ItemKinds } from './ItemKinds.js';
import { HeldEffectKinds } from './HeldEffectKinds.js';
import { BallConditions } from './BallConditions.js';
import { MoveDB } from '../battle/MoveDB.js';
import { PokemonDB } from '../pokemon/PokemonDB.js';
import { AssetPaths } from '../../config/AssetPaths.js';

/** Image of an item without a dedicated picture. */
const GENERIC_IMAGE = 'unknown.png';

const KNOWN_KINDS = new Set(Object.values(ItemKinds));
const KNOWN_EFFECTS = new Set(Object.values(HeldEffectKinds));
const KNOWN_BALL_CONDITIONS = new Set(Object.values(BallConditions));

/**
 * @param {Object|undefined} raw - Generated `ball` part
 * @returns {{rate: number, sprite: string, bonus: number, condition: string|null, order: number}|null}
 */
function readBall(raw) {
  if (!raw) return null;
  return {
    rate: Number(raw.rate) || 0,
    sprite: raw.sprite,
    bonus: Number(raw.bonus) || 0,
    condition: raw.condition || null,
    order: Number.isInteger(raw.order) ? raw.order : Number.MAX_SAFE_INTEGER
  };
}

export class ItemDB extends DataRepository {
  /** @type {ItemDB|null} */
  static _instance = null;

  /** @returns {ItemDB} */
  static getInstance() {
    if (!ItemDB._instance) ItemDB._instance = new ItemDB();
    return ItemDB._instance;
  }

  constructor() {
    super('ItemDB');
  }

  /** @protected @override */
  _build() {
    for (const [id, raw] of Object.entries(ITEMS_TABLE)) {
      this._entries.set(id, deepFreeze({
        id,
        kind: raw.kind,
        price: Number(raw.price) || 0,
        buyable: raw.buyable !== false,
        hidden: raw.hidden === true,
        category: raw.category || null,
        effect: raw.effect ? { ...raw.effect } : null,
        move: raw.move || null,
        ball: readBall(raw.ball),
        revives: raw.revives || null,
        futureOnly: raw.futureOnly === true,
        value: Number(raw.value) || 0,
        diamondValue: Number(raw.diamondValue) || 0,
        image: raw.image || null
      }));
    }
  }

  /**
   * @param {string} kind - ItemKinds value
   * @returns {Readonly<Object>[]}
   */
  getByKind(kind) {
    return this.getAll().filter((item) => item.kind === kind);
  }

  /**
   * @param {string} id
   * @returns {string} Picture of the item (pokeball SVG for balls, generic icon when missing)
   */
  getImagePath(id) {
    const item = this.getById(id);
    if (item?.ball) return AssetPaths.pokeball(item.ball.sprite);
    return AssetPaths.item(item?.image || GENERIC_IMAGE);
  }

  /**
   * @param {string} id
   * @returns {number} Catch rate of a ball (original `chance(rate)`), 0 when not a ball
   */
  getBallRate(id) {
    return this.getById(id)?.ball?.rate ?? 0;
  }

  /** @returns {Readonly<Object>[]} Every ball, in the original picker order (BALL_CYCLE) */
  getBalls() {
    return this.getByKind(ItemKinds.BALL).sort((a, b) => a.ball.order - b.ball.order);
  }

  /** @override */
  validate() {
    const problems = [];
    const moves = MoveDB.getInstance();
    const species = PokemonDB.getInstance();
    for (const item of this._entries.values()) {
      if (!KNOWN_KINDS.has(item.kind)) problems.push(this._problem(item.id, 'kind', item.kind));
      if (item.effect && !KNOWN_EFFECTS.has(item.effect.kind)) problems.push(this._problem(item.id, 'effect', item.effect.kind));
      if ((item.kind === ItemKinds.TM || item.kind === ItemKinds.HM) && !moves.has(item.move)) {
        problems.push(this._problem(item.id, 'move', item.move));
      }
      if (item.kind === ItemKinds.BALL && !(item.ball?.rate > 0)) problems.push(this._problem(item.id, 'ball', item.ball));
      if (item.ball?.condition && !KNOWN_BALL_CONDITIONS.has(item.ball.condition)) problems.push(this._problem(item.id, 'ball.condition', item.ball.condition));
      if (item.revives && !species.has(item.revives)) problems.push(this._problem(item.id, 'revives', item.revives));
    }
    return problems;
  }
}
